import os
import numpy as np
import moviepy
from moviepy import *
from moviepy import vfx, afx
from moviepy.decorators import convert_parameter_to_seconds, outplace, use_clip_fps_by_default
@convert_parameter_to_seconds(["t"])
def at(clip, t):
    return t
@outplace
def paint(clip, value):
    clip.marker = value
@use_clip_fps_by_default
def fps_of(clip, fps=None):
    return fps
c = tclip(1, fps=6)
c.marker = "original"
n = paint(c, "copy")
result = [at(c, "00:01:01.5"), at(c, (1, 2)), c.marker, n.marker, fps_of(c), fps_of(c, fps=3)]
